 def title_proof(self,row,texts):return self.profile(row)['headers']
 def productivity_proof(self):
  s=self.sources['2025'];proof=[]
  for rr in range(5,17):
   cells=[col+str(rr)for col in'CDE'];values=[s.number('Gráfico 26',a)for a in cells]
   if rr==14:require(all(v is None for v in values),'Productivity blank row changed');continue
   require(all(v is not None for v in values),'Productivity incomplete decomposition');residual=values[1]+values[2]-values[0];require(abs(residual)<=Decimal('1e-14'),'Productivity decomposition conflict');proof.append(dict(cells=cells,values=list(map(str,values)),residual=str(residual)))
